function render(lab){const s=states[lab.id],r=A.evaluate(lab.model,s);plot(lab.id,r);lab.params.forEach(p=>{$(lab.id+'-'+p.key+'-value').textContent=fmt(s[p.key],p.digits??2);});r.values.forEach((v,i)=>{$(lab.id+'-v'+i).textContent=typeof v==='string'?v:fmt(v,lab.digits?.[i]??3);});const points=r.curves.flatMap(c=>c.data).filter(d=>Number.isFinite(d.y)&&(!r.yLog||d.y>0)),xd=r.xDomain||d3.extent(points,d=>d.x),yd=r.yDomain||d3.extent(points,d=>d.y),outside=r.point&&(r.point.x<xd[0]||r.point.x>xd[1]||r.point.y<yd[0]||r.point.y>yd[1]);$(lab.id+'-result').textContent=r.summary+(outside?' 当前探针超出图示范围，读数仍按模型计算。':'');if(r.scene&&lab.scene)drawScene(lab.id,r.scene,s);const host=$(lab.id+'-lab');let status=host.querySelector('.lab-validity');if(r.validation){if(!status){status=document.createElement('p');status.className='lab-validity';$(lab.id+'-result').before(status);}status.dataset.level=r.validation.level;status.textContent=r.validation.message;status.hidden=false;}else if(status)status.hidden=true;document.dispatchEvent(new CustomEvent('lab:render',{detail:{id:host.id,model:lab.model}}));return r;}
function stop(id){const r=live.get(id);if(r)cancelAnimationFrame(r.frame);live.delete(id);const b=$(id+'-play');if(b){b.textContent='推进当前参数';b.setAttribute('aria-pressed','false');}save();}
function play(lab){if(live.has(lab.id)){stop(lab.id);return;}const p=lab.params.find(p=>p.key===lab.sweep),state=states[lab.id],apply=t=>{state[p.key]=Math.min(p.max,Math.max(p.min,p.min+Math.round(t*(p.max-p.min)/p.step)*p.step));$(lab.id+'-'+p.key).value=state[p.key];render(lab);};if(motion.matches){apply(1);save();return;}apply(0);const run={frame:0,last:0,start:performance.now()};live.set(lab.id,run);const b=$(lab.id+'-play');b.textContent='暂停示范';b.setAttribute('aria-pressed','true');function frame(now){if(document.hidden||motion.matches){stop(lab.id);return;}const t=Math.min(1,(now-run.start)/8000);if(now-run.last>60||t===1){apply(t);run.last=now;}if(t<1)run.frame=requestAnimationFrame(frame);else stop(lab.id);}run.frame=requestAnimationFrame(frame);}
const observer=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting){const id=e.target.dataset.lab;if(live.has(id))stop(id);}}));
for(const lab of spec.labs){states[lab.id]={};for(const p of lab.params){const v=saved[lab.id]?.[p.key];states[lab.id][p.key]=Number.isFinite(v)?Math.min(p.max,Math.max(p.min,p.min+Math.round((v-p.min)/p.step)*p.step)):p.value;const el=$(lab.id+'-'+p.key);el.value=states[lab.id][p.key];el.addEventListener('input',()=>{stop(lab.id);states[lab.id][p.key]=+el.value;save();render(lab);});}$(lab.id+'-reset').onclick=()=>{stop(lab.id);lab.params.forEach(p=>{states[lab.id][p.key]=p.value;$(lab.id+'-'+p.key).value=p.value;});save();render(lab);};$(lab.id+'-question').onclick=()=>{const r=render(lab),params=lab.params.map(p=>p.label+'='+fmt(states[lab.id][p.key],5)).join('；'),values=lab.values.map((label,i)=>label+'='+r.values[i]).join('；');window.showTutor(`我在学习Mo, van den Bosch & White (2010)第${spec.number}章「${spec.title}」。实验：${lab.title}。${lab.ref}。当前参数：${params}。派生读数：${values}。模型：${lab.assumptions}。扩展参考：${(lab.references||[]).map(ref=>ref.title+' '+ref.url).join('；')}。请核算公式和单位，逐步解释物理机制，区分原书内容、网页教学简化和不能由此推出的结论。`);};if(lab.sweep)$(lab.id+'-play').onclick=()=>play(lab);observer.observe($(lab.id+'-lab'));render(lab);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)[...live.keys()].forEach(stop);});motion.addEventListener('change',()=>{if(motion.matches)[...live.keys()].forEach(stop);});$('tutor-open').onclick=()=>window.showTutor(`我在阅读Mo, van den Bosch & White (2010)第${spec.number}章「${spec.title}」，印刷页${spec.pages[0]}–${spec.pages[1]}。请串联本章各节：${spec.sections.map(s=>s.num+' '+s.title).join('；')}，说明实验的假设和相互关系。该网页是原创交互导读，不是研究模拟或全文复刻。`);
